[package]
name = "wasmtime-cli"
version.workspace = true
authors.workspace = true
description = "Command-line interface for Wasmtime"
license = "Apache-2.0 WITH LLVM-exception"
documentation = "https://bytecodealliance.github.io/wasmtime/cli.html"
categories = ["wasm"]
keywords = ["webassembly", "wasm"]
repository = "https://github.com/bytecodealliance/wasmtime"
edition.workspace = true
default-run = "wasmtime"
rust-version.workspace = true
exclude = [
  'tests/disas',
  'tests/wasi-testsuite',
  'tests/spec_testsuite',
  'tests/misc_testsuite',
  'tests/component-model',
  'supply-chain',
  'docs',
  'examples/*.c',
  'examples/*.cc',
  'ci',
  '.github',
  '.claude',
  '.agents',
]

[package.metadata.binstall]
pkg-url = "{repo}/releases/download/v{version}/wasmtime-v{version}-{target-arch}-{target-family}{archive-suffix}"
bin-dir = "wasmtime-v{version}-{target-arch}-{target-family}/{bin}{binary-ext}"
pkg-fmt = "txz"
[package.metadata.binstall.overrides.x86_64-apple-darwin]
pkg-url = "{repo}/releases/download/v{version}/wasmtime-v{version}-{target-arch}-macos{archive-suffix}"
bin-dir = "wasmtime-v{version}-{target-arch}-macos/{bin}{binary-ext}"
[package.metadata.binstall.overrides.aarch64-apple-darwin]
pkg-url = "{repo}/releases/download/v{version}/wasmtime-v{version}-{target-arch}-macos{archive-suffix}"
bin-dir = "wasmtime-v{version}-{target-arch}-macos/{bin}{binary-ext}"
[package.metadata.binstall.overrides.x86_64-pc-windows-msvc]
pkg-fmt = "zip"
[package.metadata.binstall.overrides.x86_64-pc-windows-gnu]
pkg-fmt = "zip"
[package.metadata.binstall.overrides.x86_64-unknown-linux-musl]
pkg-url = "{repo}/releases/download/v{version}/wasmtime-v{version}-{target-arch}-musl{archive-suffix}"
bin-dir = "wasmtime-v{version}-{target-arch}-musl/{bin}{binary-ext}"

[lints]
workspace = true

[lib]
doctest = false

[[bin]]
name = "wasmtime"
path = "src/bin/wasmtime.rs"
doc = false

[dependencies]
wasmtime = { workspace = true, features = ['std'] }
wasmtime-cache = { workspace = true, optional = true }
wasmtime-cli-flags = { workspace = true, features = ['clap', 'toml'] }
wasmtime-cranelift = { workspace = true, optional = true }
wasmtime-environ = { workspace = true }
wasmtime-explorer = { workspace = true, optional = true }
wasmtime-wast = { workspace = true, optional = true }
wasmtime-wasi = { workspace = true, default-features = true, optional = true }
wasmtime-wasi-nn = { workspace = true, optional = true }
wasmtime-wasi-config = { workspace = true, optional = true }
wasmtime-wasi-tls = { workspace = true, optional = true }
wasmtime-wasi-keyvalue = { workspace = true, optional = true }
wasmtime-wasi-http = { workspace = true, optional = true }
wasmtime-unwinder = { workspace = true }
wasmtime-wizer = { workspace = true, optional = true, features = ['clap', 'wasmtime'] }
wasmtime-debugger = { workspace = true, optional = true }
gdbstub-component-artifact = { workspace = true, optional = true }
clap = { workspace = true }
clap_complete = { workspace = true, optional = true }
target-lexicon = { workspace = true }
wat = { workspace = true, optional = true }
serde = { workspace = true }
serde_derive = { workspace = true }
serde_json = { workspace = true }
wasmparser = { workspace = true }
tracing = { workspace = true, features = ['std'] }
log = { workspace = true }
tempfile = { workspace = true, optional = true }
object = { workspace = true, optional = true }
cranelift-codegen = { workspace = true, optional = true, features = ['disas'] }
capstone = { workspace = true, optional = true }
wasmprinter = { workspace = true, optional = true }
termcolor = { workspace = true, optional = true }
gimli = { workspace = true, optional = true }
pulley-interpreter = { workspace = true, optional = true }
smallvec = { workspace = true }

async-trait = { workspace = true }
bytes = { workspace = true }
tokio = { workspace = true, optional = true, features = [ "signal", "macros" ] }
hyper = { workspace = true, optional = true }
http = { workspace = true, optional = true }
http-body-util = { workspace = true, optional = true }
futures = { workspace = true, optional = true }
pin-project-lite = { workspace = true, optional = true }

[target.'cfg(unix)'.dependencies]
rustix = { workspace = true, features = ["mm", "process"] }

[dev-dependencies]
env_logger = { workspace = true }
log = { workspace = true }
filecheck = { workspace = true }
tempfile = { workspace = true }
tokio = { workspace = true, features = ["rt", "time", "macros", "rt-multi-thread"] }
wast = { workspace = true }
criterion = { workspace = true }
num_cpus = "1.17.0"
memchr = "2.4"
async-trait = { workspace = true }
wat = { workspace = true }
rayon = "1.5.0"
wasmtime-wast = { workspace = true, features = ['component-model'] }
wasmtime-component-util = { workspace = true }
wasmtime-test-util = { workspace = true, features = ['wasmtime-wast', 'component'] }
bstr = "1.6.0"
libc = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
walkdir = { worksp

{
  "name": "reversa",
  "version": "1.3.3",
  "description": "Transform legacy systems into executable specifications for AI coding agents",
  "bin": {
    "reversa": "bin/reversa.js"
  },
  "type": "module",
  "scripts": {
    "verify": "python3 scripts/verify-invocation.py && node scripts/test-installer-transport.mjs"
  },
  "keywords": [
    "legacy",
    "reverse-engineering",
    "specifications",
    "ai",
    "claude",
    "codex",
    "gemini",
    "cursor",
    "agents"
  ],
  "files": [
    "agents/",
    "bin/",
    "lib/",
    "templates/",
    "README.md",
    "LICENSE"
  ],
  "author": "sandeco",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sandeco/reversa.git"
  },
  "homepage": "https://github.com/sandeco/reversa",
  "bugs": {
    "url": "https://github.com/sandeco/reversa/issues"
  },
  "engines": {
    "node": ">=18.20.2"
  },
  "dependencies": {
    "chalk": "^5.3.0",
    "inquirer": "^9.2.0",
    "ora": "^7.0.1",
    "semver": "^7.6.0"
  }
}
